// Built-in sprite: 20x20 pixel frames composed from layers, emitted as one
// SVG whose frames cycle with CSS steps(). No redraw per frame: the pane
// redraws only when the state changes. Bundled Engrams now ship baked SVGs
// from the Vessel Forge; this is the fallback and the media test's control.

import type { VesselState } from './eidola-types'

export const GRID = 20

/** Character -> palette slot. '.' is transparent. */
export type Palette = {
  o: string // outline
  b: string // body
  h: string // highlight
  e: string // eye
  w: string // eye shine
  c: string // cheek
  m: string // mouth
  a: string // accent (thought dots, z's)
  r: string // alert
  y: string // sparkle
  d: string // sweat drop
}

/**
 * The built-in sprite's colors. It draws the media test's control and
 * stands in when a baked Vessel's file can't be read.
 */
export const SPRITE_PALETTE: Palette = {
  o: '#3b2f8f',
  b: '#cfc6ff',
  h: '#f4f1ff',
  e: '#1a1c2b',
  w: '#ffffff',
  c: '#ff9ec4',
  m: '#3b2f8f',
  a: '#9d93ff',
  r: '#ff5c5c',
  y: '#ffd25e',
  d: '#6fc3ff',
}

type Grid = string[][]
type Dot = [x: number, y: number, ch: keyof Palette]

// The body: a domed spirit. Rows 0-4 stay free for accessories.
const BODY = [
  '....................',
  '....................',
  '....................',
  '....................',
  '....................',
  '.......oooooo.......',
  '.....oohhbbbboo.....',
  '....ohhbbbbbbbbo....',
  '...ohbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
  '...obbbbbbbbbbbbo...',
]

// Two tail poses; frames alternate them so the spirit always drifts.
const TAILS: [string[], string[]] = [
  ['...obbbobbbbobbbo...', '....ooo.oooo.ooo....'],
  ['...obbbbobbbbobbo...', '....oooo.oooo.oo....'],
]

// Faces: dots drawn over the body.
const EYES = {
  open: [
    [6, 10, 'w'], [7, 10, 'e'], [6, 11, 'e'], [7, 11, 'e'],
    [12, 10, 'w'], [13, 10, 'e'], [12, 11, 'e'], [13, 11, 'e'],
  ],
  closed: [[6, 11, 'e'], [7, 11, 'e'], [12, 11, 'e'], [13, 11, 'e']],
  happy: [[6, 11, 'e'], [7, 10, 'e'], [8, 11, 'e'], [11, 11, 'e'], [12, 10, 'e'], [13, 11, 'e']],
  up: [
    [6, 9, 'w'], [7, 9, 'e'], [6, 10, 'e'], [7, 10, 'e'],
    [12, 9, 'w'], [13, 9, 'e'], [12, 10, 'e'], [13, 10, 'e'],
  ],
  focus: [[6, 11, 'e'], [7, 11, 'e'], [6, 10, 'e'], [12, 11, 'e'], [13, 11, 'e'], [13, 10, 'e']],
  wide: [
    [6, 9, 'w'], [7, 9, 'e'], [6, 10, 'e'], [7, 10, 'e'], [6, 11, 'e'], [7, 11, 'e'],
    [12, 9, 'w'], [13, 9, 'e'], [12, 10, 'e'], [13, 10, 'e'], [12, 11, 'e'], [13, 11, 'e'],
  ],
  left: [
    [5, 10, 'w'], [6, 10, 'e'], [5, 11, 'e'], [6, 11, 'e'],
    [11, 10, 'w'], [12, 10, 'e'], [11, 11, 'e'], [12, 11, 'e'],
  ],
  right: [
    [7, 10, 'w'], [8, 10, 'e'], [7, 11, 'e'], [8, 11, 'e'],
    [13, 10, 'w'], [14, 10, 'e'], [13, 11, 'e'], [14, 11, 'e'],
  ],
  x: [
    [5, 9, 'e'], [7, 9, 'e'], [6, 10, 'e'], [5, 11, 'e'], [7, 11, 'e'],
    [12, 9, 'e'], [14, 9, 'e'], [13, 10, 'e'], [12, 11, 'e'], [14, 11, 'e'],
  ],
} satisfies Record<string, Dot[]>

const CHEEKS: Dot[] = [[5, 12, 'c'], [14, 12, 'c']]

const MOUTH = {
  smile: [[8, 13, 'm'], [9, 14, 'm'], [10, 14, 'm'], [11, 13, 'm']],
  small: [[9, 14, 'm'], [10, 14, 'm']],
  open: [[9, 13, 'm'], [10, 13, 'm'], [9, 14, 'm'], [10, 14, 'm']],
  frown: [[8, 14, 'm'], [9, 13, 'm'], [10, 13, 'm'], [11, 14, 'm']],
  o: [[9, 14, 'm']],
} satisfies Record<string, Dot[]>

function plus(x: number, y: number, ch: keyof Palette): Dot[] {
  return [[x, y - 1, ch], [x - 1, y, ch], [x, y, ch], [x + 1, y, ch], [x, y + 1, ch]]
}

const BANG: Dot[] = [[9, 0, 'r'], [10, 0, 'r'], [9, 1, 'r'], [10, 1, 'r'], [9, 2, 'r'], [10, 2, 'r'], [9, 4, 'r'], [10, 4, 'r']]
const DROP: Dot[] = [[16, 6, 'd'], [16, 7, 'd'], [17, 7, 'd'], [16, 8, 'd']]
const Z_SMALL: Dot[] = [[16, 3, 'a'], [17, 3, 'a'], [18, 3, 'a'], [17, 4, 'a'], [16, 5, 'a'], [17, 5, 'a'], [18, 5, 'a']]
const Z_BIG: Dot[] = [
  [15, 0, 'a'], [16, 0, 'a'], [17, 0, 'a'], [18, 0, 'a'], [17, 1, 'a'], [16, 2, 'a'],
  [15, 3, 'a'], [16, 3, 'a'], [17, 3, 'a'], [18, 3, 'a'],
]

/** One frame: which tail, and which dots on top. */
type Frame = { tail: 0 | 1; dots: Dot[] }

export type Animation = {
  frames: Frame[]
  /** Seconds each frame shows. */
  frameS: number
  /** Seconds per bob up and down; 0 holds still. */
  bobS: number
}

const face = (...parts: Dot[][]): Dot[] => parts.flat()

export const ANIMATIONS: Record<VesselState, Animation> = {
  idle: {
    frameS: 0.5,
    bobS: 2,
    frames: [0, 1, 0, 1, 0, 1].map((tail, i) => ({
      tail: tail as 0 | 1,
      dots: face(i === 5 ? EYES.closed : EYES.open, CHEEKS, MOUTH.small),
    })),
  },
  thinking: {
    frameS: 0.45,
    bobS: 1.6,
    frames: [
      { tail: 0, dots: face(EYES.up, CHEEKS, MOUTH.o, [[14, 5, 'a']]) },
      { tail: 1, dots: face(EYES.up, CHEEKS, MOUTH.o, [[14, 5, 'a'], [16, 3, 'a']]) },
      { tail: 0, dots: face(EYES.up, CHEEKS, MOUTH.o, [[14, 5, 'a'], [16, 3, 'a'], [18, 1, 'a']]) },
    ],
  },
  working: {
    frameS: 0.18,
    bobS: 0.5,
    frames: [
      { tail: 0, dots: face(EYES.focus, CHEEKS, MOUTH.small, plus(18, 7, 'y')) },
      { tail: 1, dots: face(EYES.focus, CHEEKS, MOUTH.small, plus(1, 9, 'y')) },
    ],
  },
  attention: {
    frameS: 0.4,
    bobS: 0.8,
    frames: [
      { tail: 0, dots: face(EYES.wide, CHEEKS, MOUTH.o, BANG) },
      { tail: 1, dots: face(EYES.wide, CHEEKS, MOUTH.o) },
    ],
  },
  success: {
    frameS: 0.3,
    bobS: 0.6,
    frames: [
      { tail: 0, dots: face(EYES.happy, CHEEKS, MOUTH.smile, plus(2, 4, 'y'), [[17, 2, 'y']]) },
      { tail: 1, dots: face(EYES.happy, CHEEKS, MOUTH.smile, plus(17, 3, 'y'), [[2, 6, 'y']]) },
    ],
  },
  responding: {
    frameS: 0.2,
    bobS: 1.2,
    frames: [
      { tail: 0, dots: face(EYES.open, CHEEKS, MOUTH.open) },
      { tail: 1, dots: face(EYES.open, CHEEKS, MOUTH.small) },
    ],
  },
  error: {
    frameS: 0.6,
    bobS: 0,
    frames: [
      { tail: 0, dots: face(EYES.x, MOUTH.frown, DROP) },
      { tail: 1, dots: face(EYES.x, MOUTH.frown) },
    ],
  },
  waiting: {
    frameS: 0.45,
    bobS: 1.6,
    frames: [
      { tail: 0, dots: face(EYES.left, CHEEKS, MOUTH.small) },
      { tail: 1, dots: face(EYES.right, CHEEKS, MOUTH.small) },
    ],
  },
  sleeping: {
    frameS: 0.9,
    bobS: 3.6,
    frames: [
      { tail: 0, dots: face(EYES.closed, MOUTH.o, Z_SMALL) },
      { tail: 1, dots: face(EYES.closed, MOUTH.o, Z_BIG) },
    ],
  },
}

export function compose(frame: Frame): Grid {
  const rows = [...BODY, ...TAILS[frame.tail]]
  const grid = rows.map(row => row.split(''))
  for (const [x, y, ch] of frame.dots) {
    const row = grid[y]
    if (row !== undefined && x >= 0 && x < GRID) {
      row[x] = ch
    }
  }
  return grid
}

/** Horizontal runs of one color become one rect, to keep the SVG small. */
export function rects(grid: Grid, palette: Palette): string {
  const out: string[] = []
  grid.forEach((row, y) => {
    let x = 0
    while (x < row.length) {
      const ch = row[x]
      if (ch === '.') {
        x += 1
        continue
      }
      let end = x + 1
      while (end < row.length && row[end] === ch) end += 1
      const fill = palette[ch as keyof Palette] ?? '#ff00ff'
      out.push(`<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${fill}"/>`)
      x = end
    }
  })
  return out.join('')
}

const r = (n: number) => Math.round(n * 1000) / 1000

/** The whole animated Vessel for one state, as SVG markup. */
export function vesselSvg(state: VesselState, palette: Palette, size: number): string {
  const anim = ANIMATIONS[state]
  const n = anim.frames.length
  const cycle = r(anim.frameS * n)
  const slice = r(100 / n)

  const delays = anim.frames
    .map((_, i) => `.d${i}{animation-delay:-${r(((n - i) % n) * anim.frameS)}s}`)
    .join('')
  const bob =
    anim.bobS > 0
      ? `.bob{animation:bob ${anim.bobS}s steps(1,end) infinite}` +
        '@keyframes bob{0%{transform:translateY(0)}50%{transform:translateY(-1px)}100%{transform:translateY(0)}}'
      : ''
  const css =
    `.f{opacity:0;animation:fr ${cycle}s steps(1,end) infinite}.f0{opacity:1}` +
    `@keyframes fr{0%{opacity:1}${slice}%{opacity:0}100%{opacity:0}}` +
    delays +
    bob +
    '@media (prefers-reduced-motion:reduce){.f,.bob{animation:none}}'

  const frames = anim.frames
    .map((frame, i) => `<g class="f f${i === 0 ? '0' : 'n'} d${i}">${rects(compose(frame), palette)}</g>`)
    .join('')

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 -1 ${GRID} ${GRID + 1}" ` +
    `width="${size}" height="${Math.round((size * (GRID + 1)) / GRID)}" shape-rendering="crispEdges">` +
    `<style>${css}</style><g class="bob">${frames}</g></svg>`
  )
}

/** Terminal fallback: one line per state. */
export const FACES: Record<VesselState, string> = {
  idle: '( o_o )',
  thinking: '( o_o ) . o O',
  working: '( >_< ) *',
  attention: '( O_O ) !',
  success: '( ^_^ ) +',
  responding: '( o0o )',
  error: '( x_x )',
  waiting: '( o_o)>',
  sleeping: '( -_- ) z',
}

files.hooks/field.ts:
// The field engine. A scene is a sampler: for a point and a frame it gives
// a layer and a brightness. The engine samples it onto a grid sized to the
// slot, once per frame, and an ink turns the grid into SVG:
//
//   glyph     a character per cell, from a ramp of dim to dense
//   pixel     a block per cell, dithered between a layer's shades
//   particle  a dot per lit cell, sized by brightness
//
// Each layer names its ink, so one scene can mix them: a pixel creature in
// particle water. Frames cycle by CSS, locked to the wall clock, so a
// redraw for a new state carries the motion on unbroken.

export type Ink = 'glyph' | 'pixel' | 'particle'
export const INKS: readonly Ink[] = ['glyph', 'pixel', 'particle']

/** How one layer of a scene looks in each ink. */
export type LayerStyle = {
  /** glyph: characters from dim to dense; a space draws nothing. */
  chars: string
  /** pixel: shades from dim to bright. */
  shades: string[]
  /** glyph and particle: the fill, a colour or a paint server. */
  fill: string
  opacity?: number
  /** Drawn with a soft bloom. */
  isGlowing?: boolean
  /** The ink this layer draws in; the scene's when absent. */
  ink?: Ink
}

/** [layer, brightness]: layer 0 draws nothing; brightness runs 0 to 1. */
export type Cell = readonly [number, number]
export const EMPTY: Cell = [0, 0]

export type FieldScene = {
  width: number
  height: number
  /** Index 0 is the empty layer and is never drawn. */
  layers: LayerStyle[]
  /** The ink of any layer that names none. */
  ink: Ink
  /**
   * A point in pixels, a frame of `frames`: what moves there, or EMPTY.
   * `want` is the layers this pass draws; a scene may skip work for others.
   */
  sample: (x: number, y: number, frame: number, frames: number, want: ReadonlySet<number>) => Cell
  /**
   * What lies still behind it: sampled once and drawn outside the frame
   * cycle, so a backdrop costs one frame however many the scene has. A
   * cell the moving layers reach in any frame is left out of it.
   */
  still?: (x: number, y: number, want: ReadonlySet<number>) => Cell
  /**
   * How the still backdrop moves: a small drift side to side (the default),
   * or a sway from the top edge, as light shafts hang from the surface.
   */
  stillMotion?: 'drift' | 'sway'
  /** Seconds for one pass through the frames. */
  period: number
  /** Markup drawn under the field and over it; defs and CSS the scene needs. */
  under: string
  over: string
  defs: string[]
  css: string[]
}

/** Cell size in pixels and frame count per ink: what the budget allows. */
export const GRID: Record<Ink, { cw: number; ch: number; frames: number }> = {
  glyph: { cw: 8, ch: 14, frames: 8 },
  pixel: { cw: 8, ch: 8, frames: 3 },
  particle: { cw: 9, ch: 9, frames: 3 },
}

const r1 = (n: number) => Math.round(n * 10) / 10

/** A stable value in [0, 1) for a cell: the same every frame and every draw. */
export function hash(x: number, y: number): number {
  const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453
  return s - Math.floor(s)
}

/** Smooth value noise in [0, 1). */
export function noise(x: number, y: number): number {
  const xi = Math.floor(x)
  const yi = Math.floor(y)
  const xf = x - xi
  const yf = y - yi
  const u = xf * xf * (3 - 2 * xf)
  const v = yf * yf * (3 - 2 * yf)
  const a = hash(xi, yi)
  const b = hash(xi + 1, yi)
  const c = hash(xi, yi + 1)
  const d = hash(xi + 1, yi + 1)
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v
}

export const clamp01 = (n: number) => (n < 0 ? 0 : n > 1 ? 1 : n)
export const smoothstep = (a: number, b: number, x: number) => {
  const t = clamp01((x - a) / (b - a))
  return t * t * (3 - 2 * t)
}

/** 4×4 ordered dither thresholds. */
const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map(n => (n + 0.5) / 16)

type Sampled = { cols: number; rows: number; layer: Uint8Array[]; value: Float32Array[]; still?: { layer: Uint8Array; value: Float32Array } }

/** The scene sampled on one ink's grid, keeping only the layers drawn in that ink. */
function sampleAll(scene: FieldScene, cw: number, ch: number, frames: number, keep: Set<number>): Sampled {
  const cols = Math.floor(scene.width / cw)
  const rows = Math.floor(scene.height / ch)
  const layer: Uint8Array[] = []
  const value: Float32Array[] = []
  for (let f = 0; f < frames; f += 1) {
    const L = new Uint8Array(cols * rows)
    const V = new Float32Array(cols * rows)
    for (let y = 0; y < rows; y += 1) {
      for (let x = 0; x < cols; x += 1) {
        const [l, v] = scene.sample((x + 0.5) * cw, (y + 0.5) * ch, f, frames, keep)
        if (l > 0 && v > 0 && keep.has(l)) {
          L[y * cols + x] = l
          V[y * cols + x] = clamp01(v)
        }
      }
    }
    layer.push(L)
    value.push(V)
  }
  let still: Sampled['still']
  if (scene.still) {
    const L = new Uint8Array(cols * rows)
    const V = new Float32Array(cols * rows)
    for (let y = 0; y < rows; y += 1) {
      for (let x = 0; x < cols; x += 1) {
        const i = y * cols + x
        if (layer.some(f => f[i] !== 0)) {
          continue
        }
        const [l, v] = scene.still((x + 0.5) * cw, (y + 0.5) * ch, keep)
        if (l > 0 && v > 0 && keep.has(l)) {
          L[i] = l
          V[i] = clamp01(v)
        }
      }
    }
    still = { layer: L, value: V }
  }
  return { cols, rows, layer, value, still }
}

function glyphFrame(scene: FieldScene, s: Grid, cw: number, ch: number): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const texts: string[] = []
    for (let y = 0; y < s.rows; y += 1) {
      let line = ''
      let first = -1
      let last = -1
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        let c = ' '
        if (s.layer[i] === l) {
          // Lifted and jittered a little, so mid-tones don't band into rows of one character.
          const v = clamp01(Math.pow(s.value[i]!, 0.75) + (hash(x, y) - 0.5) * 0.14)
          c = style.chars[Math.min(style.chars.length - 1, Math.floor(v * style.chars.length))]!
        }
        if (c !== ' ') {
          if (first < 0) {
            first = x
          }
          last = x
        }
        line += c
      }
      if (first >= 0) {
        texts.push(`<text x="${first * cw}" y="${r1(y * ch + ch * 0.78)}" textLength="${(last - first + 1) * cw}">${line.slice(first, last + 1)}</text>`)
      }
    }
    if (texts.length) {
      out.push(layerGroup(style, texts.join(''), style.fill))
    }
  })
  return out.join('')
}

function pixelFrame(scene: FieldScene, s: Grid): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const n = style.shades.length
    const runs: string[][] = style.shades.map(() => [])
    for (let y = 0; y < s.rows; y += 1) {
      let runLevel = -1
      let runStart = 0
      const flush = (end: number) => {
        if (runLevel >= 0) {
          const len = end - runStart
          runs[runLevel]!.push(`M${runStart} ${y}h${len}v1h-${len}z`)
        }
      }
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        let level = -1
        if (s.layer[i] === l) {
          const at = s.value[i]! * (n - 1)
          const base = Math.floor(at)
          level = Math.min(n - 1, at - base > BAYER[(y % 4) * 4 + (x % 4)]! ? base + 1 : base)
        }
        if (level !== runLevel) {
          flush(x)
          runLevel = level
          runStart = x
        }
      }
      flush(s.cols)
    }
    const paths = runs.map((d, k) => (d.length ? `<path fill="${style.shades[k]}" d="${d.join('')}"/>` : '')).join('')
    if (paths) {
      out.push(layerGroup(style, paths))
    }
  })
  return out.join('')
}

/** One grid's worth: a frame, or the still backdrop. */
type Grid = { cols: number; rows: number; layer: Uint8Array; value: Float32Array }

const DOT_SIZES = [0.32, 0.55, 0.85]

function particleFrame(scene: FieldScene, s: Grid, cw: number, ch: number): string {
  const out: string[] = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const buckets: string[][] = DOT_SIZES.map(() => [])
    for (let y = 0; y < s.rows; y += 1) {
      for (let x = 0; x < s.cols; x += 1) {
        const i = y * s.cols + x
        if (s.layer[i] !== l) {
          continue
        }
        const v = s.value[i]!
        if (v < 0.08) {
          continue
        }
        const k = v < 0.4 ? 0 : v < 0.72 ? 1 : 2
        const jx = (hash(x, y) - 0.5) * cw * 0.6
        const jy = (hash(y, x) - 0.5) * ch * 0.6
        buckets[k]!.push(`M${Math.round((x + 0.5) * cw + jx)} ${Math.round((y + 0.5) * ch + jy)}h0`)
      }
    }
    const paths = buckets
      .map((d, k) => (d.length ? `<path stroke="${style.fill}" stroke-width="${r1(DOT_SIZES[k]! * cw)}" d="${d.join('')}"/>` : ''))
      .join('')
    if (paths) {
      out.push(layerGroup(style, paths))
    }
  })
  return out.join('')
}

function layerGroup(style: LayerStyle, body: string, fill?: string): string {
  const attrs =
    (fill ? ` fill="${fill}"` : '') +
    (style.opacity !== undefined ? ` opacity="${style.opacity}"` : '') +
    (style.isGlowing ? ' filter="url(#bloom)"' : '')
  return `<g${attrs}>${body}</g>`
}

const BLOOM =
  '<filter id="bloom" x="-20%" y="-20%" width="140%" height="140%"><feGaussianBlur stdDeviation="2.2" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter>'

/** What a drawing may come to: under the Svg element's 131,072, with room to spare. */
export const BUDGET = 120_000

/** The slot area GRID's cell sizes were set for: a 412 × 1442 dock. */
const REFERENCE_AREA = 412 * 1442

/**
 * The scene drawn, its frames cycling from where the clock says. Runs of
 * layers that share an ink are one pass, each on its own grid, drawn in
 * layer order. `only` draws every layer in one ink, to compare inks.
 *
 * Cells grow with the slot so a larger one costs no more: from a scale set
 * by its area, and coarser again until the drawing fits the budget.
 */
export function renderScene(scene: FieldScene, nowMs: number, only?: Ink): string {
  let scale = Math.max(1, Math.sqrt((scene.width * scene.height) / REFERENCE_AREA))
  let svg = renderAt(scene, nowMs, only, scale)
  for (let tries = 0; svg.length > BUDGET && tries < 6; tries += 1) {
    scale *= 1.2
    svg = renderAt(scene, nowMs, only, scale)
  }
  return svg
}

function renderAt(scene: FieldScene, nowMs: number, only: Ink | undefined, scale: number): string {
  const W = Math.round(scene.width)
  const H = Math.round(scene.height)
  const P = scene.period
  const clock = (nowMs / 1000) % P

  const passes: Array<{ ink: Ink; layers: number[] }> = []
  scene.layers.forEach((style, l) => {
    if (l === 0) {
      return
    }
    const ink = only ?? style.ink ?? scene.ink
    const last = passes[passes.length - 1]
    if (last?.ink === ink) {
      last.layers.push(l)
    } else {
      passes.push({ ink, layers: [l] })
    }
  })

  const css: string[] = []
  const reduced: string[] = []
  const body = passes
    .map((pass, p) => {
      const base = GRID[pass.ink]
      const cw = Math.round(base.cw * scale)
      const ch = Math.round(base.ch * scale)
      const frames = base.frames
      const s = sampleAll(scene, cw, ch, frames, new Set(pass.layers))
      const draw = (g: Grid) =>
        pass.ink === 'glyph' ? glyphFrame(scene, g, cw, ch) : pass.ink === 'pixel' ? pixelFrame(scene, g) : particleFrame(scene, g, cw, ch)
      const slot = P / frames

      let stillMarkup = s.still ? draw({ cols: s.cols, rows: s.rows, ...s.still }) : ''
      if (stillMarkup) {
        // The still backdrop drifts a little, so it never reads as frozen.
        // Pixel ink draws in cell units, the others in pixels.
        const drift = pass.ink === 'pixel' ? 0.5 : r1(cw * 0.5)
        const delay = r1(-((nowMs / 1000) % 18))
        css.push(
          scene.stillMotion === 'sway'
            ? `.s${p}{transform-box:view-box;transform-origin:${r1(W / 2)}px 0;animation:s${p} 7s ${delay}s ease-in-out infinite alternate}@keyframes s${p}{from{transform:skewX(-2.5deg)}to{transform:skewX(2.5deg)}}`
            : `.s${p}{animation:s${p} 9s ${delay}s ease-in-out infinite alternate}@keyframes s${p}{from{transform:translate(-${drift}px,0)}to{transform:translate(${drift}px,0)}}`,
        )
        reduced.push(`.s${p}`)
        stillMarkup = `<g class="s${p}">${stillMarkup}</g>`
      }

      const frameBodies = Array.from({ length: frames }, (_, f) => draw({ cols: s.cols, rows: s.rows, layer: s.layer[f]!, value: s.value[f]! }))
      let frameMarkup = ''
      if (frameBodies.some(b => b)) {
        css.push(`.p${p}{opacity:0;animation:p${p} ${P}s steps(1,end) infinite}@keyframes p${p}{0%{opacity:1}${r1(100 / frames)}%{opacity:0}100%{opacity:0}}`)
        reduced.push(`.p${p}`)
        frameMarkup = frameBodies
          .map((b, f) => {
            const delay = r1(-(((P - f * slot) % P) + clock) % P)
            return `<g class="p${p}${f === 0 ? ' f0' : ''}" style="animation-delay:${delay}s">${b}</g>`
          })
          .join('')
      }

      const attrs =
        pass.ink === 'glyph'
          ? ` font-family="ui-monospace,Menlo,Consolas,monospace" font-size="${r1(ch * 1.02)}" font-weight="700" style="white-space:pre"`
          : pass.ink === 'pixel'
            ? ` transform="scale(${cw} ${ch})" shape-rendering="crispEdges"`
            : ' fill="none" stroke-linecap="round"'
      return stillMarkup || frameMarkup ? `<g${attrs}>${stillMarkup}${frameMarkup}</g>` : ''
    })
    .join('')

  if (reduced.length) {
    css.push(`@media (prefers-reduced-motion:reduce){${reduced.join(',')}{animation:none}.f0{opacity:1}}`)
  }
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" xml:space="preserve" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">` +
    `<style>${css.join('')}${scene.css.join('')}</style><defs>${BLOOM}${scene.defs.join('')}</defs>` +
    `${scene.under}${body}${scene.over}</svg>`
  )
}

files.hooks/stage.ts:
// The stage: the Vessel set in a scene the size of the pane body, so the
// pane reads as a place rather than a small image in a large box. A glow
// and a wash in the state's colour, a soft floor shadow, motes rising at
// the state's tempo. Every layer fades to transparent before the edge, so
// an estimate a few pixels off never shows a seam, in either theme.

import type { VesselState } from './eidola-types'

// Measured on Claude Code Desktop with /eidola measure (2026-10-16): a
// 52 × 76 cell dock body drew 412 × 1443 px, a 95-column band 756 px.
export const PX_PER_COLUMN = 8
export const PX_PER_ROW = 19

/** The dark behind a band view drawn across the middle of the pane. */
export const BACKDROP = '#07090c'

/** The veil drawn over the resting scene while nothing is awake. */
export const VEIL = '#000'

/** The Svg element's limit on `source`. */
export const SVG_LIMIT = 131072

/**
 * The band's square stage, in CSS pixels. Desktop draws the band at least
 * about 170px tall whatever its tree, so this fills it rather than float.
 */
export const BAND_STAGE_PX = 140

/** Inline the pane fits its tree, so the stage asks for no more than this. */
const INLINE_ROWS = 10

export type StageSize = { width: number; height: number }

export const ACCENTS: Record<VesselState, string> = {
  idle: '#8fa3bf',
  thinking: '#8c7bff',
  working: '#ffb547',
  attention: '#ffd84a',
  success: '#5fd38d',
  responding: '#4fd1c5',
  error: '#ff5c5c',
  waiting: '#b39ddb',
  sleeping: '#4a5a80',
}

/** Seconds per glow breath. */
const BREATH: Record<VesselState, number> = {
  idle: 6,
  thinking: 3,
  working: 1.6,
  attention: 1.2,
  success: 2.4,
  responding: 2.4,
  error: 1,
  waiting: 4,
  sleeping: 9,
}

/** Seconds for a mote to rise; busier states rise faster. */
const RISE: Record<VesselState, number> = {
  idle: 14,
  thinking: 9,
  working: 5,
  attention: 7,
  success: 6,
  responding: 8,
  error: 10,
  waiting: 12,
  sleeping: 22,
}

const MOTES = 18

/** The pane body in CSS pixels, a cell short each way so it never overflows. */
export function stageSize(columns: number, rows: number, placement: 'dock' | 'inline'): StageSize {
  const usable = placement === 'inline' ? Math.min(rows, INLINE_ROWS) : rows
  return {
    width: Math.max(96, (columns - 1) * PX_PER_COLUMN),
    height: Math.max(96, (usable - 1) * PX_PER_ROW),
  }
}

/** A scene band's height: it fills the band's own minimum height. */
export const BAND_SCENE_PX = 140

/**
 * The whole pane body in CSS pixels, for a scene that fills it edge to edge.
 * The measured dock body was 4px under columns × 8 and 2px under rows × 19.
 */
export function sceneSize(columns: number, rows: number, placement: 'dock' | 'inline'): StageSize {
  const usable = placement === 'inline' ? Math.min(rows, INLINE_ROWS) : rows
  return {
    width: Math.max(96, columns * PX_PER_COLUMN - 4),
    height: Math.max(96, usable * PX_PER_ROW - 2),
  }
}

type Box = { x: number; y: number; w: number; h: number }

function viewBoxOf(svg: string): Box | undefined {
  const m = /viewBox="([-\d.]+)[ ,]+([-\d.]+)[ ,]+([\d.]+)[ ,]+([\d.]+)"/.exec(svg)
  if (!m) {
    return undefined
  }
  const [x, y, w, h] = [m[1], m[2], m[3], m[4]].map(Number) as [number, number, number, number]
  return w > 0 && h > 0 ? { x, y, w, h } : undefined
}

/** A fixed sequence in [0, 1): the motes sit in the same places every draw. */
function seeded(seed: number): () => number {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

const r1 = (n: number) => Math.round(n * 10) / 10

/**
 * The Vessel's SVG set on a stage of `size`, or undefined when it can't be:
 * no viewBox to place it by, or the result past the Svg limit. The caller
 * then draws the Vessel alone.
 */
export function stageSvg(vessel: string, state: VesselState, size: StageSize): string | undefined {
  const box = viewBoxOf(vessel)
  if (!box) {
    return undefined
  }
  const { width: W, height: H } = size
  const accent = ACCENTS[state]

  // A tall dock seats the Vessel above centre, leaving room for its shadow.
  const isTall = H > W * 1.2
  const scale = Math.min((W * 0.72) / box.w, (H * (isTall ? 0.42 : 0.78)) / box.h)
  const vw = box.w * scale
  const vh = box.h * scale
  const cx = W / 2
  const cy = isTall ? H * 0.42 : H / 2
  const vx = cx - vw / 2
  const vy = cy - vh / 2
  const reach = Math.max(vw, vh)
  // The wash is an ellipse that ends at the nearest edge on each axis, and
  // the glow a circle inside it, so neither tints an edge into a seam.
  const rx = Math.max(1, Math.min(cx, W - cx))
  const ry = Math.max(1, Math.min(cy, H - cy))
  const glowR = Math.min(reach * 0.95, rx, ry)

  const random = seeded(7)
  const rise = Math.round(Math.min(H * 0.55, reach * 2.2))
  const motes: string[] = []
  for (let i = 0; i < MOTES; i += 1) {
    const x = r1(cx + (random() - 0.5) * Math.min(W * 0.85, reach * 2))
    const y = r1(cy + vh * 0.2 + random() * vh * 0.5)
    const r = r1(0.8 + random() * 1.6)
    const dur = r1(RISE[state] * (0.7 + random() * 0.6))
    const delay = r1(-random() * dur)
    motes.push(`<circle class="eds-mote" cx="${x}" cy="${y}" r="${r}" style="animation-duration:${dur}s;animation-delay:${delay}s"/>`)
  }

  // The Vessel nested at its place: its own width/height dropped, the slot's set.
  const nested = vessel.replace(/<svg\b([^>]*)>/, (_match, attrs: string) => {
    const kept = attrs.replace(/\s(width|height|x|y|preserveAspectRatio)="[^"]*"/g, '')
    return `<svg x="${r1(vx)}" y="${r1(vy)}" width="${r1(vw)}" height="${r1(vh)}" preserveAspectRatio="xMidYMid meet"${kept}>`
  })

  const css =
    `.eds-glow{animation:eds-breath ${BREATH[state]}s ease-in-out infinite alternate}` +
    '@keyframes eds-breath{from{opacity:.6}to{opacity:1}}' +
    `.eds-mote{fill:${accent};opacity:0;animation-name:eds-rise;animation-timing-function:linear;animation-iteration-count:infinite}` +
    `@keyframes eds-rise{0%{transform:translateY(0);opacity:0}15%{opacity:.75}80%{opacity:.4}100%{transform:translateY(-${rise}px);opacity:0}}` +
    '@media (prefers-reduced-motion:reduce){.eds-glow,.eds-mote{animation:none}.eds-mote{opacity:.35}}'

  const out =
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">` +
    `<style>${css}</style>` +
    '<defs>' +
    `<radialGradient id="eds-wash" gradientUnits="userSpaceOnUse" cx="0" cy="0" r="1" ` +
    `gradientTransform="translate(${r1(cx)} ${r1(cy)}) scale(${r1(rx)} ${r1(ry)})">` +
    `<stop offset="0" stop-color="${accent}" stop-opacity=".14"/><stop offset=".45" stop-color="${accent}" stop-opacity=".07"/>` +
    `<stop offset=".75" stop-color="${accent}" stop-opacity=".02"/><stop offset="1" stop-color="${accent}" stop-opacity="0"/></radialGradient>` +
    `<radialGradient id="eds-glow" gradientUnits="userSpaceOnUse" cx="${r1(cx)}" cy="${r1(cy)}" r="${r1(glowR)}">` +
    `<stop offset="0" stop-color="${accent}" stop-opacity=".42"/><stop offset=".35" stop-color="${accent}" stop-opacity=".2"/>` +
    `<stop offset=".65" stop-color="${accent}" stop-opacity=".06"/><stop offset="1" stop-color="${accent}" stop-opacity="0"/></radialGradient>` +
    '<radialGradient id="eds-floor"><stop offset="0" stop-color="#000" stop-opacity=".45"/><stop offset="1" stop-color="#000" stop-opacity="0"/></radialGradient>' +
    '</defs>' +
    `<rect width="${W}" height="${H}" fill="url(#eds-wash)"/>` +
    `<rect class="eds-glow" width="${W}" height="${H}" fill="url(#eds-glow)"/>` +
    `<ellipse cx="${r1(cx)}" cy="${r1(vy + vh * 1.04)}" rx="${r1(vw * 0.45)}" ry="${r1(Math.max(3, vh * 0.05))}" fill="url(#eds-floor)"/>` +
    `<g>${motes.join('')}</g>` +
    nested +
    '</svg>'

  return out.length <= SVG_LIMIT ? out : undefined
}

